import {SEGMENTS,DIGITAL,STAGES,DEFAULT_SETTINGS,newBusiness,field,get,clean,safeURL,whatsappURL,normalizeText,parseCSV,duplicateCandidates,validateSettings,lastVerified} from './lib/domain.js';
import {permitted,canRetain,projectBusiness,exportCSV,promptAllowed} from './lib/permissions.js';
import {calculateScore} from './lib/score.js';
import {generateBriefing,generateForAI,approach} from './lib/briefing.js';
import {demoBusinesses} from './lib/demo.js';
import {readLocal,persist,persistBatch,remove,persistSettings,writeLocal} from './lib/store.js';
import {configureSupabase,authSession,ensureSession,login,register,logout,clearSession,loadCloud} from './lib/supabase.js';
import {esc,icon,date,badge,labels,card,safeLink,fieldDisplay} from './lib/ui.js';
import {searchBusinesses} from './lib/search.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const local=readLocal();let businesses=local.businesses,settings=local.settings,demo=null,view='grid',page=1,nav='search',tab='summary',current=null,stagedImport=[],busy=false;
let config={search:'not_configured',audit:'not_configured',access:'not_configured'},accessKey='',toastTimer,searchController=null;
const detail=$('#detail-dialog'),formDialog=$('#form-dialog');
const list=()=>demo||businesses;
const business=id=>list().find(b=>b.id===id);
const options=(obj,selected='')=>Object.entries(obj).map(([k,v])=>`<option value="${esc(k)}" ${String(k)===String(selected)?'selected':''}>${esc(v)}</option>`).join('');
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5500);}
function errorBox(e,target='#form-error'){$(target)?.replaceChildren(document.createTextNode(e.message||String(e)));}
function event(b,text){b.events.unshift({at:new Date().toISOString(),text:clean(text,4000)});b.events=b.events.slice(0,100);b.updatedAt=new Date().toISOString();}
async function save(b){await persist(b,businesses,settings);render();}
async function mutation(b,fn){const previous=structuredClone(b);try{fn();await save(b);}catch(e){Object.keys(b).forEach(k=>delete b[k]);Object.assign(b,previous);render();throw e;}}
function download(text,name,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copy(text,editor){try{await navigator.clipboard.writeText(text);toast('Conteúdo copiado integralmente.');}catch{if(editor){editor.focus();editor.select();}toast('Cópia automática indisponível. O texto foi selecionado: use Ctrl+C ou baixe o arquivo.');}}
function filterValues(){return {query:$('#local-query').value,segments:$$('#segment-options input:checked').map(x=>x.value),digital:$('#filter-digital').value,priority:$('#filter-priority').value,contact:$('#filter-contact').value,coverage:$('#filter-coverage').value,stage:$('#filter-stage').value,date:$('#filter-date').value,favorite:$('#filter-favorite').checked};}
function filtered(){const f=filterValues();return list().filter(b=>{
  if(!canRetain(b))return false;
  const s=calculateScore(b,settings);
  if(nav==='saved'&&!b.favorite)return false;
  if(nav!=='deals'&&!f.stage&&(b.stage==='Não contatar'||b.lifecycle!=='active'))return false;
  if(f.query&&!normalizeText(Object.values(b.fields).map(f=>f.value).join(' ')+' '+SEGMENTS[b.segment]).includes(normalizeText(f.query)))return false;
  if(f.segments.length&&!f.segments.includes(b.segment))return false;
  if(f.digital&&(b.assessments.digital?.value||'inconclusive')!==f.digital)return false;
  if(f.priority&&s.priority!==f.priority)return false;
  if(f.contact==='whatsapp'&&!whatsappURL(b))return false;
  if(['phone','email'].includes(f.contact)&&!get(b,f.contact))return false;
  if(f.contact==='unknown'&&(whatsappURL(b)||['phone','email'].some(k=>b.fields[k]?.confirmed)))return false;
  if(f.coverage==='incomplete'&&s.coverage>=70)return false;
  if(f.coverage&&f.coverage!=='incomplete'&&s.coverage<Number(f.coverage))return false;
  if(f.stage&&b.stage!==f.stage)return false;
  if(f.date&&lastVerified(b).slice(0,10)<f.date)return false;
  if(f.favorite&&!b.favorite)return false;return true;
}).sort((a,b)=>{const v=$('#sort').value;if(v==='name')return get(a,'name').localeCompare(get(b,'name'),'pt-BR');if(v==='updated')return b.updatedAt.localeCompare(a.updatedAt);const x=calculateScore(a,settings),y=calculateScore(b,settings);return Number(y.eligible)-Number(x.eligible)||y.score-x.score;});}
function renderChips(){const f=filterValues(),chips=[];for(const [k,v]of Object.entries(f)){if(k==='segments')v.forEach(s=>chips.push({key:s,type:'segment',label:SEGMENTS[s]}));else if(v)chips.push({key:k,type:'filter',label:k==='favorite'?'Favoritos':k==='query'?`Busca: ${v}`:k==='digital'?DIGITAL[v]:k==='priority'?labels[v]:k==='contact'?`Contato: ${v}`:k==='coverage'?`Cobertura: ${v}`:String(v)});}
  $('#active-filters').innerHTML=chips.map(c=>`<button class="chip" data-action="remove-filter" data-type="${c.type}" data-key="${esc(c.key)}">${esc(c.label)} <span aria-hidden="true">×</span><span class="sr-only" hidden>Remover filtro</span></button>`).join('');$('#filter-count').textContent=chips.length||'';}
function render(){
  const items=filtered(),all=list(),scores=all.map(b=>calculateScore(b,settings)),analyzed=scores.filter(s=>s.eligible),high=scores.filter(s=>s.priority==='high').length;
  $('#stats').innerHTML=[['Comércios na base',all.length,'Registros carregados neste espaço','globe'],['Alta prioridade',high,`${analyzed.length} com análise suficiente`,'chart'],['Oportunidades salvas',all.filter(b=>b.favorite).length,'Favoritos registrados por você','bookmark'],['Propostas e vendas',all.filter(b=>['Proposta enviada','Fechado'].includes(b.stage)).length,'Etapas registradas por você','brief']].map(([t,n,d,i])=>`<div class="stat"><div class="stat-label">${esc(t)}${icon(i)}</div><strong>${n}</strong><small>${esc(d)}</small></div>`).join('');
  $('#saved-count').textContent=all.filter(b=>b.favorite).length;$('#result-count').textContent=items.length;
  $('#results-title').firstChild.textContent=nav==='saved'?'Oportunidades salvas ':nav==='deals'?'Suas negociações ':'Comércios para explorar ';
  renderChips();$('#mode-pill').innerHTML=`<span class="tiny-dot"></span>${demo?'Demonstração':authSession()?'Dados reais · conta':'Dados reais · local'}`;
  $('#mode-banner').hidden=!demo;$('#mode-banner').textContent=demo?'MODO DEMONSTRAÇÃO · Todas as empresas são fictícias. Alterações ficam só nesta sessão e contatos não são acionáveis.':'';
  $('#demo-toggle').textContent=demo?'Voltar aos dados reais':'Explorar demonstração';
  $('#attribution').hidden=!items.some(b=>b.sources.some(s=>s.id.startsWith('osm-')));
  $$('[data-brand]').forEach(e=>e.textContent=settings.appName==='Prospecta IA'?'prospecta IA':settings.appName);document.title=`${settings.appName} · Prospecção com contexto`;
  if(nav==='settings')renderSettings();
  const totalPages=Math.max(1,Math.ceil(items.length/8));page=Math.min(Math.max(1,page),totalPages);const slice=items.slice((page-1)*8,page*8);
  if(!items.length){$('#results').innerHTML=`<div class="empty-state"><span class="empty-symbol">${icon(all.length?'filter':'radar')}</span><h3>${all.length?'Nenhum comércio com esses filtros':'Toda boa conversa começa com contexto.'}</h3><p>${all.length?'Ajuste os filtros locais para explorar sua base. Seus registros continuam salvos.':'Cadastre seu primeiro comércio ou importe uma base autorizada. Você também pode conhecer o fluxo com empresas fictícias.'}</p><div class="empty-actions">${all.length?'<button class="button secondary" data-action="clear-filters">Limpar filtros</button>':'<button class="button primary" data-action="new">'+icon('plus')+'Cadastrar comércio</button><button class="button secondary" data-action="toggle-demo">Ver demonstração</button>'}</div></div>`;}
  else if(nav==='deals'){$('#results').innerHTML=`<div class="deal-board">${STAGES.map(stage=>{const arr=items.filter(b=>b.stage===stage);return `<section class="deal-column"><h3>${esc(stage)} <span>${arr.length}</span></h3>${arr.length?arr.map(b=>card(b,settings)).join(''):'<p>Nenhum registro nesta etapa.</p>'}</section>`;}).join('')}</div>`;}
  else if(view==='table'&&window.innerWidth>=768){$('#results').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Comércio</th><th>Índice</th><th>Cobertura</th><th>Prioridade</th><th>Ação</th></tr></thead><tbody>${slice.map(b=>{const s=calculateScore(b,settings);return `<tr><td>${esc(get(b,'name'))}<p>${esc(SEGMENTS[b.segment])}</p>${b.demo?'<small>Fictício</small>':''}</td><td>${s.score}/100</td><td>${s.coverage}%</td><td>${badge(s.priority)}</td><td><button class="button secondary compact" data-action="detail" data-id="${esc(b.id)}">Ver análise</button></td></tr>`;}).join('')}</tbody></table></div>`;}
  else $('#results').innerHTML=`<div class="cards">${slice.map(b=>card(b,settings)).join('')}</div>`;
  $('#pagination').hidden=!items.length||nav==='deals';$('#pagination').innerHTML=`<span>${items.length?`${(page-1)*8+1}–${Math.min(page*8,items.length)} de ${items.length}`:'0 resultados'}</span><div><button class="icon-button" data-action="prev" aria-label="Página anterior" ${page<=1?'disabled':''}>‹</button><span>${page}/${totalPages}</span><button class="icon-button" data-action="next" aria-label="Próxima página" ${page>=totalPages?'disabled':''}>›</button></div>`;
  $$('.view-toggle button').forEach(b=>{const selected=b.dataset.action===`view-${view}`;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected);});
}
function navigate(value){nav=value;$('#settings-page').hidden=nav!=='settings';$('#search-page').hidden=nav==='settings';$$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===value));$('#breadcrumb').textContent={search:'Buscar comércios',saved:'Oportunidades salvas',deals:'Negociações',settings:'Configurações'}[value];$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');page=1;render();}
function clearFilters(){$('#local-query').value='';$$('#segment-options input').forEach(x=>x.checked=false);$$('.filters select,.filters input[type="date"]').forEach(x=>x.value='');$('#filter-favorite').checked=false;page=1;render();}
function showForm(title,content,submit,id='generic-form'){ $('#form-content').innerHTML=`<div class="dialog-head"><div><h2 id="form-title">${esc(title)}</h2></div><button class="icon-button" type="button" data-action="close-form" aria-label="Fechar">${icon('x')}</button></div><div class="form-body">${content}<p class="feedback form-errors" id="form-error" role="alert"></p></div>`;if(!formDialog.open)formDialog.showModal();if(submit)$('#'+id)?.addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter;if(button)button.disabled=true;try{$('#form-error').textContent='';await submit(new FormData(e.target),e.target);}catch(error){errorBox(error);}finally{if(button)button.disabled=false;}});}
const textInput=(key,label,value='',type='text',extra='')=>`<label>${esc(label)}<input name="${key}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function businessForm(existing){
  if(demo){toast('Volte aos dados reais para cadastrar ou editar um comércio.');return;}
  const b=existing;
  showForm(b?'Editar dados do comércio':'Cadastrar comércio',`<form id="business-form"><div class="info-banner">Use dados comerciais que você tem autorização para registrar. Campos ausentes ficam como “Não localizado”. Confirme país e DDD do WhatsApp, sem adivinhar dígitos.</div><div class="form-grid">${textInput('name','Nome do comércio *',b?get(b,'name'):'','text','required maxlength="180"')}<label>Segmento<select name="segment">${options(SEGMENTS,b?.segment||'other')}</select></label>${textInput('city','Cidade *',b?get(b,'city'):settings.city,'text','required maxlength="80"')}${textInput('uf','UF *',b?get(b,'uf'):settings.uf,'text','required pattern="[A-Za-z]{2}" maxlength="2"')}${textInput('district','Bairro',b?get(b,'district'):'')}${textInput('address','Endereço',b?get(b,'address'):'')}<label class="full">Descrição<textarea name="description" rows="3" maxlength="4000">${esc(b?get(b,'description'):'')}</textarea></label><label class="full">Serviços/produtos confirmados<textarea name="services" rows="2">${esc(b?get(b,'services'):'')}</textarea></label>${textInput('hours','Horários',b?get(b,'hours'):'')}${textInput('website','Site encontrado — associação a confirmar',b?get(b,'website'):'','url')}${textInput('phone','Telefone comercial',b?get(b,'phone'):'')}${textInput('email','E-mail comercial',b?get(b,'email'):'','email')}${textInput('whatsapp','WhatsApp com país e DDD (+55...) ou link wa.me',b?get(b,'whatsapp'):'')}${textInput('social','Canal oficial / rede social',b?get(b,'social'):'','url')}<label class="full">Identidade visual observada (somente material inspecionado)<textarea name="visual" rows="2">${esc(b?get(b,'visual'):'')}</textarea></label>${textInput('source','URL da fonte ou identificação da confirmação *','','text','required maxlength="1000"')}<label>Data da verificação<input name="verifiedAt" type="date" required value="${new Date().toISOString().slice(0,10)}" max="${new Date().toISOString().slice(0,10)}"></label><label class="check full"><input type="checkbox" name="authorized" required>Tenho autorização para registrar e manter estes dados comerciais.</label><label class="check full"><input type="checkbox" name="export">As fontes permitem exportar os dados informados.</label><label class="check full"><input type="checkbox" name="ai">As fontes permitem usar estes dados em serviços de IA.</label><label class="check full"><input type="checkbox" name="whatsappConfirmed" ${b?.fields.whatsapp?.confirmed?'checked':''}>Confirmei que o WhatsApp pertence ao comércio e contém país e DDD.</label><label class="check full"><input type="checkbox" name="phoneConfirmed" ${b?.fields.phone?.confirmed?'checked':''}>Confirmei que telefone/e-mail são canais comerciais atuais.</label></div><div class="form-actions"><button class="button secondary" type="button" data-action="close-form">Cancelar</button><button class="button primary">${b?'Salvar correções':'Cadastrar comércio'}</button></div></form>`,async f=>{
    const vals=Object.fromEntries(f);vals.uf=vals.uf.toUpperCase();
    for(const k of ['website','social'])if(vals[k]&&!safeURL(vals[k]))throw new Error('Informe URLs HTTP/HTTPS válidas.');
    if(f.has('whatsappConfirmed')&&vals.whatsapp){const test={fields:{whatsapp:{value:vals.whatsapp,status:'user',confirmed:true}}};if(!whatsappURL(test)||(!vals.whatsapp.startsWith('https://wa.me/')&&!vals.whatsapp.startsWith('+')))throw new Error('Use WhatsApp no formato internacional +55... ou link https://wa.me/... com país e DDD.');}
    const source={id:crypto.randomUUID(),label:clean(vals.source,1000),url:safeURL(vals.source)||'',collectedAt:new Date().toISOString(),expiresAt:new Date(Date.now()+settings.retentionDays*86400000).toISOString(),permissions:{retain:true,export:f.has('export'),ai:f.has('ai')}};
    const fresh=newBusiness(vals,source);for(const v of Object.values(fresh.fields))v.verifiedAt=vals.verifiedAt+'T12:00:00.000Z';fresh.fields.whatsapp.confirmed=f.has('whatsappConfirmed');for(const k of ['phone','email'])fresh.fields[k].confirmed=f.has('phoneConfirmed');
    if(b){await mutation(b,()=>{b.sources.push(source);for(const [k,v]of Object.entries(fresh.fields))if(get(b,k)!==v.value||b.fields[k]?.status==='conflict'||['whatsapp','phone','email'].includes(k)&&b.fields[k]?.confirmed!==v.confirmed)b.fields[k]=v;b.segment=fresh.segment;event(b,'Dados comerciais corrigidos manualmente. Confirmações anteriores não foram sobrescritas por busca externa.');});}
    else{const duplicates=duplicateCandidates(businesses,fresh);if(duplicates.length)throw new Error('Já existe um registro com nome e cidade semelhantes. Abra a ficha e confira a unidade/endereço antes de criar outra.');businesses.push(fresh);try{await save(fresh);}catch(e){businesses.pop();throw e;}}
    formDialog.close();toast('Comércio salvo. Registre as evidências para concluir a análise.');if(b&&detail.open)renderDetail();
  },'business-form');
}
const ASSESS_LABELS={identity:'Identidade da empresa e da unidade confirmada',recentActivity:'Atividade recente em canal oficial',consistentInfo:'Informações comerciais atuais e consistentes',useCase:'Caso de uso claro para um site (hipótese)',informationNeed:'Necessidade de organizar informações (hipótese)',benefit:'Benefício específico identificado (hipótese)',contactChecked:'Pesquisa de canais de contato realizada',interest:'Manifestação explícita de interesse',nextStep:'Próximo passo/prazo combinado'};
function evidenceForm(b){
  showForm('Registrar evidências e análise',`<form id="evidence-form"><div class="info-banner">Cada critério precisa de uma justificativa e uma fonte. “Não” é um resultado conhecido; “Não avaliado” não aumenta a cobertura.</div><div class="evaluation"><label>Situação digital<select name="digital">${options(DIGITAL,b.assessments.digital?.value||'inconclusive')}</select></label><label>O que foi verificado e quais as limitações?<textarea name="digitalReason" required rows="3">${esc(b.assessments.digital?.reason||'')}</textarea></label><label class="check"><input type="checkbox" name="sufficient" ${b.assessments.digital?.sufficient?'checked':''}>Consultei fontes suficientes para essa classificação. Ausência confirmada exige confirmação do comércio; 403/timeout são inconclusivos.</label>${Object.entries(ASSESS_LABELS).map(([k,label])=>`<div class="evaluation-row"><label for="e-${k}">${esc(label)}<small>${['useCase','informationNeed','benefit'].includes(k)?'Conclusão comercial justificada; não é fato comprovado.':'Somente com evidência ou registro explícito.'}</small></label><select id="e-${k}" name="${k}">${options({'':'Não avaliado',yes:'Sim',no:'Não'},b.assessments[k]?.value===true?'yes':b.assessments[k]?.value===false?'no':'')}</select><textarea name="reason-${k}" aria-label="Justificativa: ${esc(label)}" placeholder="Justificativa e fonte específica" rows="2">${esc(b.assessments[k]?.reason||'')}</textarea></div>`).join('')}${textInput('source','Fonte ou identificação do registro *','','text','required')}<label class="check"><input type="checkbox" name="authorized" required>Tenho autorização para registrar as evidências e confirmo as justificativas acima.</label><label class="check"><input type="checkbox" name="export">Permitir exportação das novas evidências.</label><label class="check"><input type="checkbox" name="ai">Permitir envio das novas evidências a IA.</label></div><div class="form-actions"><button type="button" class="button secondary" data-action="close-form">Cancelar</button><button class="button primary">Salvar análise e recalcular</button></div></form>`,async f=>{
    await mutation(b,()=>{const source={id:crypto.randomUUID(),label:clean(f.get('source')),url:safeURL(f.get('source'))||'',collectedAt:new Date().toISOString(),permissions:{retain:true,export:f.has('export'),ai:f.has('ai')},expiresAt:new Date(Date.now()+30*86400000).toISOString()};b.sources.push(source);
      const assessments={digital:{...field(f.get('digital'),source.id),reason:clean(f.get('digitalReason')),sufficient:f.has('sufficient')}};
      for(const key of Object.keys(ASSESS_LABELS)){const val=f.get(key),reason=clean(f.get('reason-'+key));if(val){if(!reason)throw new Error('Preencha a justificativa de cada critério avaliado.');assessments[key]={...field('',source.id),value:val==='yes',reason,status:['useCase','informationNeed','benefit'].includes(key)?'inference':'user'};}}
      b.assessments=assessments;const snapshot=calculateScore(b,settings);snapshot.expiresAt=source.expiresAt;b.scoreHistory.push(snapshot);b.scoreHistory=b.scoreHistory.slice(-30);event(b,`Análise ${snapshot.version}: ${snapshot.score}/100, cobertura ${snapshot.coverage}%.`);
    });formDialog.close();renderDetail();toast('Análise registrada com histórico de pontuação.');
  },'evidence-form');
}
function selectDetail(id,selected='summary'){current=id;tab=selected;const hash=`#empresa=${encodeURIComponent(id)}`;if(location.hash!==hash)history.pushState(null,'',hash);renderDetail();if(!detail.open)detail.showModal();}
function renderDetail(){const b=business(current);if(!b)return;b.prompts=b.prompts.filter(p=>promptAllowed(b,p,'retain'));const s=calculateScore(b,settings),tabs={summary:'Resumo',digital:'Presença digital',opportunity:'Oportunidade',prompt:'Prompt do site',commercial:'Contato e negociação',sources:'Fontes e histórico'};
  $('#detail-content').innerHTML=`<div class="dialog-head"><span class="avatar">${esc(get(b,'name').slice(0,2).toUpperCase())}</span><div>${b.demo?'<p class="demo-label">DEMONSTRAÇÃO · EMPRESA FICTÍCIA</p>':''}<h2 id="detail-title">${esc(get(b,'name','Comércio'))}</h2><p>${esc(SEGMENTS[b.segment])} · ${esc(get(b,'city','Cidade a confirmar'))} ${badge(s.priority)}</p></div><button class="icon-button" data-action="close-detail" aria-label="Fechar ficha">${icon('x')}</button></div><div class="dialog-tabs" role="tablist" aria-label="Seções da ficha">${Object.entries(tabs).map(([k,v])=>`<button role="tab" id="tab-${k}" aria-controls="detail-panel" aria-selected="${k===tab}" tabindex="${k===tab?'0':'-1'}" class="${k===tab?'active':''}" data-action="tab" data-tab="${k}">${v}</button>`).join('')}</div><div class="dialog-body" id="detail-panel" role="tabpanel" aria-labelledby="tab-${tab}">${detailBody(b,s)}</div>`;
  if(tab==='prompt'){
    const last=b.prompts.at(-1);if(last)$('#prompt-editor').value=last.text;
    $('#prompt-build').addEventListener('submit',async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await buildPrompt(b,new FormData(e.target));}catch(error){toast(error.message);}finally{button.disabled=false;}});
    $('#prompt-versions')?.addEventListener('change',e=>{const p=b.prompts[Number(e.target.value)];if(p)$('#prompt-editor').value=p.text;});
  }
  if(tab==='commercial'){
    $('#approach-message').value=approach(b,settings);updateWhatsApp(b);
    $('#approach-message').addEventListener('input',()=>updateWhatsApp(b));
    $('#commercial-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target);try{await mutation(b,()=>{const stage=f.get('stage');if(stage!==b.stage){event(b,`Etapa registrada pelo usuário: ${b.stage} → ${stage}.`);b.stage=stage;}b.notes=clean(f.get('notes'));b.nextAction=clean(f.get('nextAction'));b.nextActionAt=clean(f.get('nextActionAt'),30);event(b,'Notas e próxima ação atualizadas pelo usuário.');});renderDetail();toast('Negociação atualizada.');}catch(error){toast(error.message);}});
  }
}
function detailBody(b,s){
  if(tab==='summary')return `<div class="detail-grid"><div><div class="info-box"><h3>O negócio em contexto</h3><p>${esc(get(b,'description','Descrição não localizada. Preencha com dados confirmados.'))}</p><div class="detail-actions"><button class="button secondary compact" data-action="edit" data-id="${esc(b.id)}">Editar dados</button><button class="button primary compact" data-action="evidence" data-id="${esc(b.id)}">Registrar evidências</button></div><dl class="data-grid">${['services','hours','address','district','city','uf'].map(k=>fieldDisplay(b,k,settings)).join('')}</dl></div><div class="info-box"><h3>Identidade observada</h3><p>${esc(get(b,'visual','Nenhum material visual foi inspecionado/registrado. A direção visual do briefing será uma proposta nova.'))}</p><h3 class="metrics-note">Hipóteses de público e posicionamento</h3><p>Precisam ser validadas com o comércio. Não são inferidas como fatos pela plataforma.</p></div></div><div><div class="info-box"><h3>Índice de oportunidade</h3><div class="score-big">${s.score}<span> / 100</span></div><p>${s.coverage}% dos critérios avaliados</p><div class="detail-actions">${badge(s.priority)}</div><p>Organiza a abordagem; não representa chance de compra. Análise ${esc(s.version)}.</p><button class="button secondary compact" data-action="tab" data-tab="opportunity">Entender pontuação ${icon('arrow')}</button></div><div class="info-box"><h3>O que verificar a seguir</h3><ul class="pending-list">${s.pending.slice(0,5).map(p=>`<li>${esc(p)}</li>`).join('')||'<li>Nenhum critério pendente na regra atual. Revise a validade das fontes.</li>'}</ul></div></div></div>`;
  if(tab==='digital')return `<div class="info-banner">${esc(DIGITAL[b.assessments.digital?.value]||DIGITAL.inconclusive)}. ${esc(b.assessments.digital?.reason||'A ausência de um site na fonte de busca não comprova ausência de site próprio.')}</div><div class="info-box"><h3>Domínios e canais encontrados</h3><dl class="data-grid">${['website','social'].map(k=>fieldDisplay(b,k,settings)).join('')}</dl><p class="flow-note">Site: ${safeLink(get(b,'website'))}. Confirme se o domínio corresponde à empresa e à unidade. Uma página de homônimo não pode ser associada automaticamente.</p><div class="detail-actions"><button class="button secondary" data-action="refresh-source" data-id="${esc(b.id)}">Atualizar cadastro da fonte</button><button class="button primary" data-action="audit" data-id="${esc(b.id)}">Auditoria leve autorizada</button></div><p>Confirme a identidade e a autorização na própria ficha para analisar o domínio. Bloqueio, timeout ou erro de robô resultam em análise inconclusiva.</p></div><div class="info-box"><h3>Auditorias registradas</h3>${b.audits.length?b.audits.slice().reverse().map(a=>`<p>${date(a.at,settings,true)} · ${safeLink(a.url)} · ${esc(a.limits||'Cenário de teste')}</p>${a.tests.map(t=>`<div class="audit-item"><div><strong>${esc(t.id)}</strong><span class="badge ${t.status==='fail'?'medium':'neutral'}">${t.status==='fail'?'Problema verificado':t.status==='pass'?'Critério atendido':'Não avaliado'}</span></div><p>${esc(t.evidence)}</p>${t.impact?`<p>Impacto possível: ${esc(t.impact)} Sugestão: ${esc(t.suggestion)}</p>`:''}</div>`).join('')}`).join(''):'<p>Nenhuma medição executada. Não há notas de desempenho estimadas.</p>'}</div>`;
  if(tab==='opportunity')return `<div class="info-banner">${s.score}/100 · ${s.coverage}% de cobertura · Regra ${esc(s.version)}. Necessidade digital e problemas de site são mutuamente exclusivos; valores desconhecidos não são normalizados.</div><div class="score-parts">${s.parts.map(p=>`<div class="score-part"><div><strong>${esc(p.label)}</strong><span>${p.points.toLocaleString('pt-BR')} / ${p.max}</span></div><p>${esc(p.reason)} · Peso efetivamente avaliado: ${Math.round(p.covered)}/${p.max}.</p></div>`).join('')}</div><div class="info-box mb"><h3>Pendências</h3><ul class="pending-list">${s.pending.map(p=>`<li>${esc(p)}</li>`).join('')||'<li>Critérios cobertos. Validar interesse com uma conversa real.</li>'}</ul><div class="detail-actions"><button class="button primary" data-action="evidence" data-id="${esc(b.id)}">Registrar evidências</button></div><h3>Solução proposta (hipótese)</h3><p>Organizar os serviços e os canais confirmados em um site acessível e facilitar o contato. A solução depende de validação com a empresa; não há promessa de aumento de vendas.</p></div><div class="info-box"><h3>Histórico das regras</h3>${b.scoreHistory.length?b.scoreHistory.slice().reverse().map(x=>`<p>${date(x.at,settings,true)} · ${esc(x.version)} · ${x.score}/100 · ${x.coverage}% cobertura</p>`).join(''):'<p>Registre uma análise para criar o primeiro snapshot. Alterações de configuração não reescrevem snapshots anteriores.</p>'}</div>`;
  if(tab==='prompt')return `<div class="info-banner">Gerador por template estruturado. A versão “Para IA” remove campos sem permissão de envio a IA e exportação. Nenhuma API de IA é chamada.</div><form id="prompt-build"><div class="prompt-options">${textInput('objective','Objetivo do site',b.prompts.at(-1)?.options?.objective||'')}${textInput('style','Estilo proposto',b.prompts.at(-1)?.options?.style||'')}<label>Páginas / estrutura<textarea name="pages" rows="2">${esc(b.prompts.at(-1)?.options?.pages||'')}</textarea></label><label>Funcionalidades<textarea name="features" rows="2">${esc(b.prompts.at(-1)?.options?.features||'')}</textarea></label><label>Uso do briefing<select name="destination"><option value="ai">Para IA · somente dados permitidos</option value="internal">Uso interno · dados exportáveis</option></select></label><label class="check"><input type="checkbox" name="authorized" required>Tenho autorização para exportar as instruções adicionais que inseri.</label></div><button class="button primary">${icon('spark')}Gerar nova versão</button></form><div class="detail-actions"><button class="button secondary" data-action="copy-prompt">${icon('copy')}Copiar integralmente</button><button class="button secondary" data-action="download-prompt">${icon('download')}Baixar .txt</button><button class="button secondary" data-action="save-prompt">Salvar edição</button></div><label>Briefing completo · editor<textarea id="prompt-editor" class="prompt-editor" placeholder="Gere uma versão para visualizar o briefing completo."></textarea></label>${b.prompts.length?`<label class="prompt-versions">Versões salvas<select id="prompt-versions">${b.prompts.map((p,i)=>`<option value="${i}" ${i===b.prompts.length-1?'selected':''}>${date(p.at,settings,true)} · ${p.destination==='ai'?'Para IA':'Uso interno'} · versão ${i+1}</option>`).join('')}</select></label>`:''}`;
  if(tab==='commercial')return `<div class="detail-grid"><div><div class="info-box"><h3>Contatos comerciais</h3><dl class="data-grid">${['phone','whatsapp','email','address'].map(k=>fieldDisplay(b,k,settings)).join('')}</dl><div class="detail-actions">${get(b,'phone')?`<button class="button secondary compact" data-action="copy-phone">${icon('copy')}Copiar telefone</button>`:''}${get(b,'email')?`<button class="button secondary compact" data-action="copy-email">${icon('copy')}Copiar e-mail</button>`:''}${safeURL(get(b,'social'))?safeLink(get(b,'social'),'Abrir canal informado'):''}</div>${get(b,'address')?`<p>${safeLink('https://www.openstreetmap.org/search?query='+encodeURIComponent([get(b,'address'),get(b,'city'),get(b,'uf')].join(', ')),'Pesquisar endereço no mapa (confirmar localização)')}</p>`:''}<p class="flow-note">Telefone isolado não comprova WhatsApp. ${whatsappURL(b)?'WhatsApp confirmado no registro.':'WhatsApp não confirmado ou não localizado.'}</p></div><div class="info-box"><h3>Abordagem para revisar</h3><label>Mensagem editável<textarea id="approach-message" rows="5"></textarea></label><div class="detail-actions" id="whatsapp-action"></div><p>Abrir o aplicativo não envia a mensagem e não altera a etapa comercial. Registre o resultado depois da conversa.</p></div></div><div class="info-box"><h3>Organização comercial</h3><form id="commercial-form" class="column-fields"><label>Etapa<select name="stage">${options(Object.fromEntries(STAGES.map(s=>[s,s])),b.stage)}</select></label><label>Notas privadas<textarea name="notes" rows="5" maxlength="4000">${esc(b.notes)}</textarea></label>${textInput('nextAction','Próxima ação',b.nextAction)}${textInput('nextActionAt','Data da próxima ação',b.nextActionAt||'','date')}<button class="button primary">Salvar negociação</button></form><div class="detail-actions"><button class="button secondary" data-action="favorite" data-id="${esc(b.id)}">${icon('star')}${b.favorite?'Remover favorito':'Favoritar'}</button></div></div></div>`;
  return `<div class="info-banner">“Verificado na fonte” indica que a fonte publicou o dado; não garante que ele continue sendo usado. Revise conflitos, permissões e validade antes da abordagem.</div>${b.providerNotice?`<p class="flow-note">${esc(b.providerNotice)}</p>`:''}${b.sources.map(s=>`<div class="source-card"><strong>${esc(s.label)}</strong><div>${safeLink(s.url)}</div><small>Coletado: ${date(s.collectedAt,settings,true)} · Validade: ${s.expiresAt?date(s.expiresAt,settings):'revisar periodicamente'}</small><p class="source-permissions">Retenção: ${s.permissions?.retain?'permitida':'não permitida'} · Exportação: ${s.permissions?.export?'permitida':'não permitida'} · IA: ${s.permissions?.ai?'permitida':'não permitida'}</p><small>${esc(s.license||'Autorização declarada pelo usuário')}</small></div>`).join('')}<div class="info-box"><h3>Campos e estados</h3><dl class="data-grid">${Object.keys(b.fields).filter(k=>k!=='description').map(k=>fieldDisplay(b,k,settings)).join('')}</dl></div><div class="info-box"><h3>Histórico de alterações e interações</h3><ul class="history-list">${b.events.map(e=>`<li><small>${date(e.at,settings,true)}</small>${esc(e.text)}</li>`).join('')||'<li>Nenhuma interação comercial registrada.</li>'}</ul><div class="detail-actions"><button class="button danger" data-action="delete" data-id="${esc(b.id)}">Excluir este registro</button></div></div>`;
}
function updateWhatsApp(b){const blocked=b.stage==='Não contatar';const url=whatsappURL(b,$('#approach-message').value);$('#whatsapp-action').innerHTML=blocked?'<p class="warning-text">Não contatar: canal de abordagem suprimido.</p>':url?`<a class="button whatsapp" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${icon('phone')}Abrir WhatsApp para revisar</a>`:'<p class="flow-note">Sem WhatsApp confirmado. Nenhum botão com número fictício é criado.</p>';}
async function buildPrompt(b,f){const opts={objective:clean(f.get('objective'),1500),style:clean(f.get('style'),1500),pages:clean(f.get('pages'),3000),features:clean(f.get('features'),3000)},destination=f.get('destination'),text=(destination==='ai'?generateForAI:generateBriefing)(b,settings,opts);
  const scoped=projectBusiness(projectBusiness(b,destination==='ai'?'ai':'export'),'export'),dates=scoped.sources.map(s=>s.expiresAt).filter(Boolean).sort();
  const allAI=destination==='ai';await mutation(b,()=>{b.prompts.push({id:crypto.randomUUID(),text,options:opts,destination,at:new Date().toISOString(),sourceIds:scoped.sources.map(s=>s.id),expiresAt:dates[0]||null,permissions:{retain:true,export:true,ai:allAI}});b.prompts=b.prompts.slice(-20);event(b,'Briefing gerado por template; nenhuma análise de IA executada.');});renderDetail();toast('Briefing completo gerado e salvo.');}
async function api(route,body){const publicSearch=route==='search'||route==='details';if(!publicSearch)await ensureSession();const headers={'Content-Type':'application/json'};if(!publicSearch&&authSession())headers.Authorization=`Bearer ${authSession().access_token}`;else if(!publicSearch&&accessKey)headers['x-access-key']=accessKey;const r=await fetch('/api/'+route,{method:'POST',headers,body:JSON.stringify(body),signal:AbortSignal.timeout(65000)});let data;try{data=await r.json();}catch{throw new Error('Backend indisponível ou resposta inválida.');}if(!r.ok)throw new Error(data.message||'Falha na integração.');return data;}
async function refreshSource(b){if(!b.providerId){toast('Registro manual: use Editar dados para atualizar com nova evidência.');return;}
  const data=await api('details',{id:b.providerId}),fresh=data.business;
  const differences=Object.keys(fresh.fields).filter(k=>get(fresh,k)&&get(fresh,k)!==get(b,k));
  showForm('Revisar atualização da fonte',`<form id="refresh-form"><p class="flow-note">A busca nunca sobrescreve dados confirmados por você. Revise os campos divergentes. Salvar registra o conflito sem substituir seu valor atual.</p>${differences.map(k=>`<div class="source-card"><strong>${esc(k)}</strong><p>Atual: ${esc(get(b,k,'Não localizado'))}</p><p>Nova fonte: ${esc(get(fresh,k))}</p></div>`).join('')||'<p>Nenhuma diferença encontrada nos campos preenchidos da fonte.</p>'}<div class="form-actions"><button class="button primary">Registrar verificação</button></div></form>`,async()=>{await mutation(b,()=>{b.sources.push(...fresh.sources.map(s=>({...s,id:s.id+'-'+Date.now()})));for(const k of differences){b.fields[k].conflicts=[...(b.fields[k].conflicts||[]),{value:get(fresh,k),source: fresh.sources[0].url,at:new Date().toISOString()}];b.fields[k].status='conflict';}event(b,`Fonte consultada novamente: ${differences.length} divergências registradas. Corrija manualmente após confirmar com a empresa.`);});formDialog.close();renderDetail();},'refresh-form');}
function importForm(){if(demo){toast('Volte aos dados reais para importar.');return;}stagedImport=[];showForm('Importar base autorizada',`<form id="import-form"><div class="info-banner">CSV UTF-8 com cabeçalho name e até 200 linhas. A importação não presume confirmação de identidade, ausência de site ou WhatsApp.</div><div class="column-fields"><button type="button" class="button secondary" data-action="csv-template">${icon('download')}Baixar modelo CSV vazio</button><label>Arquivo CSV<input name="file" type="file" accept=".csv,text/csv" required class="file-input"></label>${textInput('source','Origem/licença dos dados *','','text','required')}<label class="check"><input type="checkbox" name="retain" required>Tenho autorização para importar e reter os dados.</label><label class="check"><input type="checkbox" name="export">A origem permite exportação.</label><label class="check"><input type="checkbox" name="ai">A origem permite envio a serviços de IA.</label></div><div id="import-preview" class="flow-note"></div><div class="form-actions"><button class="button primary">Revisar importação</button></div></form>`,async(f,form)=>{
    const file=f.get('file');if(!file||file.size>1000000)throw new Error('Selecione um CSV de até 1 MB.');
    const rows=parseCSV(await file.text());if(!rows.length)throw new Error('O arquivo está vazio.');
    const now=new Date().toISOString(),source={id:crypto.randomUUID(),label:clean(f.get('source')),url:safeURL(f.get('source'))||'',collectedAt:now,expiresAt:new Date(Date.now()+settings.retentionDays*86400000).toISOString(),permissions:{retain:true,export:f.has('export'),ai:f.has('ai')}};
    const candidates=rows.map(r=>newBusiness(r,source)),duplicates=[];stagedImport=[];
    for(const b of candidates){if(duplicateCandidates([...businesses,...stagedImport],b).length)duplicates.push(get(b,'name'));else stagedImport.push(b);}
    $('#import-preview').innerHTML=`<strong>${stagedImport.length} registros novos · ${duplicates.length} possíveis duplicatas separadas para revisão</strong><ul>${candidates.slice(0,10).map(b=>`<li>${esc(get(b,'name'))} · ${esc(get(b,'city','Cidade não localizada'))}</li>`).join('')}</ul>${duplicates.length?`<p>Duplicatas não importadas: ${esc(duplicates.join(', '))}. Confira unidade/endereço antes de cadastrar manualmente.</p>`:''}${stagedImport.length?'<button type="button" class="button primary" data-action="confirm-import">Confirmar importação revisada</button>':''}`;
    form.addEventListener('input',()=>{stagedImport=[];$('#import-preview').textContent='Arquivo ou permissões alterados. Revise novamente antes de importar.';},{once:true});
  },'import-form');}
function renderSettings(){
  $('#settings-page').innerHTML=`<div class="settings-heading"><p class="eyebrow">SEU ESPAÇO, SUAS REGRAS</p><h1>Configurações</h1><p>Personalize sua apresentação, as regras de prioridade e as conexões.</p></div><div class="settings-grid"><div class="info-box"><h3>Perfil e preferências</h3><form id="settings-form">${textInput('appName','Nome da plataforma',settings.appName,'text','required maxlength="60"')}${textInput('agency','Nome da agência',settings.agency)}${textInput('seller','Nome do vendedor',settings.seller)}${textInput('portfolio','URL do portfólio',settings.portfolio,'url')}${textInput('agencyContact','Contato da agência',settings.agencyContact)}<div class="form-grid">${textInput('city','Cidade inicial',settings.city,'text','required')}${textInput('uf','UF inicial',settings.uf,'text','required maxlength="2"')}</div>${textInput('timezone','Fuso IANA',settings.timezone,'text','required')}${textInput('retentionDays','Retenção local (dias)',settings.retentionDays,'number','min="1" max="3650" required')}<p class="form-help">Dados locais sem atualização nesse prazo deixam de ser retidos na próxima gravação. Em conta, a revisão e exclusão dos registros são manuais. Não há rotina remota agendada.</p><button class="button primary">Salvar preferências</button></form></div><div class="column-fields"><div class="info-box"><h3>Regras de prioridade</h3><form id="rules-form"><p class="form-help">Os pesos devem somar 100. Snapshots antigos preservam os valores e a versão usados na análise.</p><div class="weight-grid">${Object.entries(settings.weights).map(([k,v])=>textInput(k,{digital:'Necessidade digital',operation:'Operação',fit:'Adequação do site',contact:'Contato utilizável',interest:'Interesse registrado'}[k],v,'number','min="0" max="100" required')).join('')}</div><div class="weight-grid">${textInput('high','Alta a partir de',settings.thresholds.high,'number','min="1" max="100" required')}${textInput('medium','Média a partir de',settings.thresholds.medium,'number','min="0" max="99" required')}${textInput('coverage','Cobertura mínima (%)',settings.thresholds.coverage,'number','min="0" max="100" required')}</div><button class="button primary">Salvar nova versão das regras</button></form></div><div class="info-box"><h3>Integrações e armazenamento</h3><div class="integration-line"><span>Busca · OpenStreetMap</span><span class="badge neutral">${config.search==='available'?'Configurada':'Não configurada'}</span></div><div class="integration-line"><span>Auditoria de sites</span><span class="badge neutral">${config.audit==='available'?'Pronta · autorize na ficha':'Desativada'}</span></div><div class="integration-line"><span>Gerador de briefing</span><span class="badge neutral">Template local</span></div><div class="integration-line"><span>Supabase</span><span class="badge neutral">${config.supabase?authSession()?'Conta conectada':'Configurado · entrar':'Não configurado'}</span></div><p class="flow-note">Busque sem cadastro ou login. Os resultados ficam salvos neste navegador. A conta é opcional para sincronizar registros entre dispositivos.</p><form id="access-form" ${config.access==='access_key'?'':'hidden'}><label>Código de acesso às integrações<input name="key" type="password" autocomplete="off" placeholder="Somente nesta sessão"></label><button class="button secondary">Usar código nesta sessão</button></form><div class="detail-actions"><button class="button secondary" data-action="auth">${authSession()?'Gerenciar conta':'Entrar / criar conta'}</button><button class="button secondary" data-action="delete-all">Excluir dados deste espaço</button></div></div></div></div>`;
  $('#settings-form').addEventListener('submit',async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target)),next=validateSettings({...settings,...f,uf:f.uf.toUpperCase()});await persistSettings(next,businesses);settings=next;render();toast('Preferências salvas.');}catch(error){toast(error.message);}});
  $('#rules-form').addEventListener('submit',async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target)),next=validateSettings({...settings,weights:Object.fromEntries(Object.keys(settings.weights).map(k=>[k,Number(f[k])])),thresholds:{high:Number(f.high),medium:Number(f.medium),coverage:Number(f.coverage)},rulesVersion:settings.rulesVersion+1});await persistSettings(next,businesses);settings=next;render();toast('Nova versão das regras salva. Histórico preservado.');}catch(error){toast(error.message);}});
  $('#access-form').addEventListener('submit',e=>{e.preventDefault();accessKey=new FormData(e.target).get('key');e.target.reset();toast('Código mantido somente na memória desta sessão.');});
}
async function connectCloud(){
  const cloud=await loadCloud();businesses=cloud.businesses;settings={...structuredClone(DEFAULT_SETTINGS),...cloud.settings};demo=null;
  const email=authSession().user.email||'Sua conta';$('#account-name').textContent=email;$('#account-caption').textContent='Sincronizado com sua conta';$('#account-avatar').textContent=email[0].toUpperCase();
  $('#city').value=settings.city;$('#uf').value=settings.uf;
  if(cloud.truncated)toast('Limite de 1.000 registros carregados. Refine a base antes de ampliar o uso.');
}
function authForm(){if(authSession()){showForm('Sua conta',`<p>Conectado como ${esc(authSession().user.email)}. Os registros desta conta são sincronizados com Supabase. Os dados locais não são enviados automaticamente.</p><div class="form-actions"><button class="button secondary" data-action="logout">Sair da conta</button></div>`);return;}if(!config.supabase){toast('Supabase não configurado. O espaço local continua funcionando neste navegador.');return;}
  showForm('Acessar seu espaço',`<form id="auth-form"><p class="flow-note">Cada conta acessa apenas os próprios dados. Registros locais não são importados automaticamente.</p><div class="column-fields">${textInput('email','E-mail','','email','required autocomplete="username"')}${textInput('password','Senha','','password','required minlength="6" autocomplete="current-password"')}<label>Ação<select name="mode"><option value="login">Entrar na minha conta</option><option value="register">Criar conta</option></select></label></div><div class="form-actions"><button class="button primary">Continuar</button></div></form>`,async f=>{
    if(f.get('mode')==='register'){await register(f.get('email'),f.get('password'));toast('Cadastro solicitado. Confirme seu e-mail, se exigido pelo projeto, e depois entre.');return;}
    await login(f.get('email'),f.get('password'));
    try{await connectCloud();}catch(e){clearSession();throw e;}
    formDialog.close();render();toast('Conta conectada.');
  },'auth-form');}
function confirmDelete(b){showForm('Excluir registro?',`<p>Você vai excluir ${esc(get(b,'name'))}, suas notas, análises e prompts deste espaço. Essa ação não é desfeita pelo aplicativo.</p><div class="form-actions"><button class="button secondary" data-action="close-form">Cancelar</button><button class="button danger" data-action="confirm-delete" data-id="${esc(b.id)}">Excluir registro</button></div>`);}
document.addEventListener('click',async e=>{
  const target=e.target.closest('[data-action],[data-nav]');if(!target)return;
  if(target.dataset.nav){navigate(target.dataset.nav);return;}
  const action=target.dataset.action,b=target.dataset.id?business(target.dataset.id):current?business(current):null;
  try{
    if(action==='cancel-search'){searchController?.abort();return;}
    if(action==='menu'){const isOpen=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',isOpen);}
    if(action==='toggle-demo'){demo=demo?null:demoBusinesses();page=1;if(detail.open)detail.close();render();}
    if(action==='new')businessForm();if(action==='edit'&&b)businessForm(b);
    if(action==='import')importForm();
    if(action==='csv-template')download('name,segment,city,uf,district,address,description,services,hours,website,phone,email,whatsapp,social\r\n','modelo-comercios.csv','text/csv;charset=utf-8');
    if(action==='confirm-import'){
      if(!stagedImport.length)throw new Error('Revise o arquivo antes de confirmar.');target.disabled=true;
      let saved=0;for(const candidate of [...stagedImport]){businesses.push(candidate);try{await persist(candidate,businesses,settings);saved++;stagedImport=stagedImport.filter(x=>x.id!==candidate.id);}catch(error){businesses=businesses.filter(x=>x.id!==candidate.id);throw new Error(`${saved} registros salvos antes da falha. ${error.message} Os pendentes podem ser tentados novamente.`);}}
      formDialog.close();page=1;render();toast(`${saved} comércios importados. Identidade e situação digital aguardam análise.`);
    }
    if(action==='detail')selectDetail(b.id);if(action==='prompt')selectDetail(b.id,'prompt');if(action==='contact')selectDetail(b.id,'commercial');
    if(action==='tab'){tab=target.dataset.tab;renderDetail();$('#tab-'+tab)?.focus();}
    if(action==='close-detail')detail.close();if(action==='close-form')formDialog.close();
    if(action==='favorite'&&b){await mutation(b,()=>{b.favorite=!b.favorite;b.updatedAt=new Date().toISOString();});if(detail.open)renderDetail();}
    if(action==='evidence'&&b)evidenceForm(b);
    if(action==='copy-prompt'||action==='download-prompt'||action==='save-prompt'){
      const text=$('#prompt-editor')?.value;if(!text)throw new Error('Gere um briefing primeiro.');
      const selectedIndex=$('#prompt-versions')?Number($('#prompt-versions').value):b.prompts.length-1;
      if(!promptAllowed(b,b.prompts[selectedIndex],'export'))throw new Error('Permissão ou validade do briefing mudou. Gere uma versão com dados permitidos.');
      if(action==='copy-prompt')await copy(text,$('#prompt-editor'));
      if(action==='download-prompt')download(text,`briefing-${get(b,'name').replace(/[^a-zA-Z0-9-]/g,'-').slice(0,60)}.txt`);
      if(action==='save-prompt'){
        if(!b.prompts.length)throw new Error('Gere uma versão antes de salvar uma edição.');
        const last=b.prompts.at(-1);await mutation(b,()=>{b.prompts.push({...structuredClone(last),id:crypto.randomUUID(),text,at:new Date().toISOString()});b.prompts=b.prompts.slice(-20);event(b,'Edição manual de briefing salva. Revisar permissões do conteúdo acrescentado antes de compartilhar.');});renderDetail();toast('Nova versão salva.');
      }
    }
    if(action==='copy-phone')await copy(get(b,'phone'));if(action==='copy-email')await copy(get(b,'email'));
    if(action==='audit'){
      if(b.demo)throw new Error('Auditorias externas são desativadas na demonstração.');
      if(b.assessments.identity?.value!==true)throw new Error('Confirme a identidade e a associação do domínio antes de analisar.');
      const url=get(b,'website');if(!safeURL(url))throw new Error('Cadastre um domínio válido primeiro.');
      showForm('Auditoria leve',`<form id="audit-form"><p>Domínio: ${esc(url)}. Serão consultadas uma página e as regras de acesso. Não haverá inspeção visual ou navegação completa.</p><label class="check flow-note"><input name="authorized" type="checkbox" required>Tenho autorização para analisar esta página e reter/exportar as evidências.</label><div class="form-actions"><button class="button primary">Executar análise</button></div></form>`,async()=>{const audit=await api('audit',{url,authorized:true});await mutation(b,()=>{b.audits.push(audit);b.audits=b.audits.slice(-10);event(b,'Auditoria leve realizada. Revise a classificação digital antes de recalcular o índice.');});formDialog.close();renderDetail();toast('Auditoria registrada. Critérios não medidos continuam pendentes.');},'audit-form');
    }
    if(action==='refresh-source'){if(b.demo)throw new Error('Atualização externa desativada na demonstração.');target.disabled=true;await refreshSource(b);target.disabled=false;}
    if(action==='export'){if(demo)throw new Error('Exportação de leads da demonstração desativada. Gere um briefing fictício para testar o download.');const selected=filtered().filter(b=>permitted(b,b.fields.name,'export'));if(!selected.length)throw new Error('Nenhum registro com permissão vigente de exportação.');download(exportCSV(selected),'prospecta-oportunidades.csv','text/csv;charset=utf-8');toast(`${selected.length} registros exportados, com remoção dos campos restritos.`);}
    if(action==='view-grid'||action==='view-table'){view=action==='view-grid'?'grid':'table';render();}
    if(action==='prev'){page--;render();}if(action==='next'){page++;render();}
    if(action==='filters'){$('#filters').classList.toggle('open');target.setAttribute('aria-expanded',$('#filters').classList.contains('open'));}
    if(action==='clear-filters')clearFilters();
    if(action==='all-segments'){$$('#segment-options input').forEach(x=>x.checked=false);page=1;render();}
    if(action==='remove-filter'){if(target.dataset.type==='segment')$$('#segment-options input').find(x=>x.value===target.dataset.key).checked=false;else{const k=target.dataset.key,el=k==='query'?$('#local-query'):$('#filter-'+k);if(el.type==='checkbox')el.checked=false;else el.value='';}page=1;render();}
    if(action==='auth')authForm();
    if(action==='logout'){await logout();const data=readLocal();businesses=data.businesses;settings=data.settings;$('#account-name').textContent='Espaço local';$('#account-caption').textContent='Neste navegador';$('#account-avatar').textContent='L';formDialog.close();render();toast('Você saiu da conta.');}
    if(action==='delete')confirmDelete(b);
    if(action==='confirm-delete'){const original=[...list()];if(demo)demo=demo.filter(x=>x.id!==b.id);else businesses=businesses.filter(x=>x.id!==b.id);try{await remove(b,businesses,settings);}catch(error){if(demo)demo=original;else businesses=original;throw error;}formDialog.close();detail.close();render();toast('Registro excluído.');}
    if(action==='delete-all')showForm('Excluir dados deste espaço?',`<p>Todos os ${list().length} registros do espaço ${demo?'de demonstração':authSession()?'da sua conta':'local deste navegador'} serão excluídos. Essa ação não pode ser desfeita pelo aplicativo. Prefira exportar os dados autorizados antes.</p><div class="form-actions"><button class="button secondary" data-action="close-form">Cancelar</button><button class="button danger" data-action="confirm-delete-all">Excluir todos os registros</button></div>`);
    if(action==='confirm-delete-all'){target.disabled=true;for(const record of [...list()]){const remaining=list().filter(x=>x.id!==record.id);await remove(record,remaining,settings);if(demo)demo=remaining;else businesses=remaining;}formDialog.close();render();toast('Registros excluídos. Preferências preservadas.');}
  }catch(error){toast(error.message||'Não foi possível concluir a ação.');target.disabled=false;}
});
$('#search-form').addEventListener('submit',async e=>{
  e.preventDefault();if(busy)return;
  if(demo){$('#local-query').value=$('#external-query').value;page=1;render();toast('Busca local nos cenários fictícios. Nenhuma consulta externa realizada.');return;}
  if(config.search!=='available'){toast('Fonte de busca não configurada. Use cadastro/importação ou configure a integração no servidor.');return;}
  const f=Object.fromEntries(new FormData(e.target));f.segments=filterValues().segments;
  busy=true;searchController=new AbortController();$('#search-button').disabled=true;$('#results').innerHTML=`<div class="loading-state">${icon('radar')}<p id="search-progress" role="status">Consultando comércios na região…</p><p>A fonte pode levar alguns segundos. Seus registros continuam salvos.</p><button type="button" class="button secondary" data-action="cancel-search">Cancelar busca</button></div>`;
  const progress=setTimeout(()=>{const message=$('#search-progress');if(message)message.textContent='A fonte está demorando. Tentando recuperar a consulta…';},7000);
  try{const data=await searchBusinesses(f,{signal:searchController.signal});if(searchController.signal.aborted)return;const incoming=[];let duplicate=0;for(const b of data.businesses){if(duplicateCandidates([...businesses,...incoming],b).length){duplicate++;continue;}if(canRetain(b))incoming.push(b);}
    if(incoming.length){const merged=[...businesses,...incoming];await persistBatch(incoming,merged,settings);businesses=merged;}
    page=1;$('#source-note').textContent=data.notice;toast(`${incoming.length} registros adicionados; ${duplicate} possíveis duplicatas preservadas sem sobrescrever. ${data.state==='partial'?'Resposta parcial da fonte.':''}`);
  }catch(error){const message=error.name==='AbortError'?'Busca cancelada. Seus registros foram preservados.':error.message||'Busca indisponível. Seus registros foram preservados.';toast(message);$('#source-note').textContent=message;}finally{clearTimeout(progress);searchController=null;busy=false;$('#search-button').disabled=false;render();}
});
$$('.filters input,.filters select,#sort').forEach(e=>e.addEventListener(e.tagName==='INPUT'&&e.type!=='checkbox'?'input':'change',()=>{page=1;render();}));
detail.addEventListener('close',()=>{if(location.hash.startsWith('#empresa='))history.replaceState(null,'',location.pathname+location.search);});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#empresa=')){const id=decodeURIComponent(location.hash.slice(9));if(business(id))selectDetail(id);}else if(detail.open)detail.close();});
detail.addEventListener('keydown',e=>{if(e.target.getAttribute('role')==='tab'&&['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('[role="tab"]'),i=tabs.indexOf(e.target),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tab=tabs[next].dataset.tab;renderDetail();$('#tab-'+tab)?.focus();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!formDialog.open&&!detail.open){$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
window.addEventListener('resize',()=>{if(view==='table')render();});
$$('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));
$('#segment-options').innerHTML='<button type="button" class="text-button" data-action="all-segments">Todos os segmentos</button>'+Object.entries(SEGMENTS).map(([k,v])=>`<label><input type="checkbox" value="${k}">${esc(v)}</label>`).join('');
$$('#segment-options input').forEach(e=>e.addEventListener('change',()=>{page=1;render();}));
$('#uf').innerHTML=options(Object.fromEntries('AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' ').map(s=>[s,s])),settings.uf);$('#city').value=settings.city;
$('#filter-digital').innerHTML='<option value="">Todas as situações</option>'+options(DIGITAL);
$('#filter-stage').innerHTML='<option value="">Todas as etapas</option>'+options(Object.fromEntries(STAGES.map(s=>[s,s])));
render();if(local.error)toast(local.error);
try{const r=await fetch('/api/config',{signal:AbortSignal.timeout(8000)});if(!r.ok)throw new Error();config=await r.json();configureSupabase(config.supabase);$('#provider-badge').textContent=config.search==='available'?'OpenStreetMap · amostra parcial':'Fonte não configurada';$('#source-note').textContent=config.search==='available'?'Busca livre, sem cadastro ou login. Os resultados são salvos automaticamente neste navegador; com conta conectada, são sincronizados. Cobertura parcial do OpenStreetMap.':'Fonte de busca não configurada. Cadastre ou importe uma base autorizada para começar.';}
catch{$('#provider-badge').textContent='Backend não disponível';$('#source-note').textContent='Cadastro e importação locais disponíveis. Execute o backend para configurar as integrações.';}
if(authSession()){try{await connectCloud();render();}catch(error){clearSession();toast('Não foi possível restaurar sua conta. Entre novamente. Seus dados locais foram preservados.');}}
$('#search-button').disabled=false;
if(location.hash.startsWith('#empresa=')){const id=decodeURIComponent(location.hash.slice(9));if(business(id))selectDetail(id);}
